SELECT p.PartiNo, p.PartiKodu AS [Parti No], Format(p.Tarih,"dd.mm.yyyy") AS Kabul, m.AdSoyad AS Müşteri, p.ZeytinMiktari_Kg AS [Net Zeytin], Format(p.SikimTarihi,"dd.mm.yyyy") AS Sıkım, p.CikanYag_Kg AS [Çıkan Yağ], IIf(Nz(p.ZeytinMiktari_Kg,0)>0 And Nz(p.CikanYag_Kg,0)>0,Format(p.CikanYag_Kg/p.ZeytinMiktari_Kg*100,"0.00"),Null) AS [Randıman %], p.OdemeTipi AS Ödeme, p.HakYagiOrani_Yuzde AS [Oran %], p.HakYagi_Kg AS [Hakyağı Kg], IIf(p.OdemeTipi Like "S*",Format(Nz(p.TLTutari,0),"#,##0.00"),"-") AS [Ücret TL], p.MusteriKalanYag_Kg AS [Kalan Yağ], IIf(p.TeslimTarihi Is Not Null,"Teslim Edildi",IIf(p.SikimTarihi Is Not Null And Nz(p.CikanYag_Kg,0)>0,"Üretildi","Kabul")) AS Durum, p.Sezon, p.Tarih AS TarihHam, Val(Nz(p.PartiKodu,"0")) AS PartiSira
FROM tbl_Parti AS p LEFT JOIN tbl_Musteri AS m ON p.MusteriID=m.MusteriID;